<?php
require_once __DIR__ . '/../../../backend/config/database.php';
require_once __DIR__ . '/../../../backend/helpers/functions.php';
require_once __DIR__ . '/../../../backend/auth.php';
require_once __DIR__ . '/../../../backend/helpers/spmb_workflow.php';
portal_require_auth(['admin','kasir']);

$spmbLevels = [];
foreach (fetch_school_units($pdo) as $unitRow) {
    $value = trim((string)($unitRow['subtitle'] ?: $unitRow['title']));
    if ($value !== '') $spmbLevels[$value] = $unitRow['title'];
}
$academicYears = spmb_academic_years();
$unitLabels = school_admin_units();
$statuses = ['baru'=>'Baru','verifikasi'=>'Verifikasi','lulus'=>'Lulus','cadangan'=>'Cadangan','ditolak'=>'Ditolak','daftar_ulang'=>'Daftar Ulang'];
function spmb_portal_rupiah(int|float|string|null $value): string { return 'Rp ' . number_format((float)$value,0,',','.'); }
function spmb_csv_safe(mixed $value): string { $text=(string)$value; return preg_match('/^\s*[=+\-@]/u',$text) ? "'".$text : $text; }

if (isset($_GET['proof'])) {
    $stmt = $pdo->prepare('SELECT proof_path FROM spmb_payment_claims WHERE id=?');
    $stmt->execute([(int)$_GET['proof']]);
    spmb_stream_proof((string)$stmt->fetchColumn());
}

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    portal_verify_csrf();
    try {
        $action = (string)($_POST['action'] ?? '');
        $id = (int)($_POST['id'] ?? 0);
        if ($action === 'manual_registration') {
            $result = spmb_validate_and_save($pdo,$_POST,null,$spmbLevels,'manual');
            if (!$result['success']) throw new RuntimeException(implode(' ', $result['errors']));
            portal_log($pdo,'manual_registration','Input manual SPMB ' . $result['registration_number'],school_unit_slug((string)$_POST['level']));
            portal_flash('success','Pendaftar berhasil dibuat: '.$result['registration_number'].'. Bagikan tautan pembayaran dari kartu detail.');
            header('Location: ' . SITE_URL . '/portal/payments?created=' . $result['id']); exit;
        }
        if ($action === 'update_registration') {
            $stmt=$pdo->prepare('SELECT * FROM spmb_registrations WHERE id=?');$stmt->execute([$id]);$existing=$stmt->fetch();
            if (!$existing) throw new RuntimeException('Pendaftar tidak ditemukan.');
            $name=trim((string)($_POST['student_name']??''));$parent=trim((string)($_POST['parent_name']??''));$wa=trim((string)($_POST['whatsapp']??''));
            $nisn=trim((string)($_POST['nisn']??''));$class=trim((string)($_POST['entry_class']??''));$status=(string)($_POST['registration_status']??'');$due=trim((string)($_POST['total_due']??'0'));
            if ($name===''||$parent===''||$wa==='') throw new RuntimeException('Nama siswa, orang tua, dan WhatsApp wajib diisi.');
            if ($nisn!==''&&!preg_match('/^[0-9]{10}$/',$nisn)) throw new RuntimeException('NISN harus 10 angka.');
            if ($class!==''&&!in_array($class,spmb_entry_classes($existing['level']),true)) throw new RuntimeException('Kelas tujuan tidak sesuai unit.');
            if (!isset($statuses[$status])||!preg_match('/^(0|[1-9][0-9]{0,11})$/',$due)) throw new RuntimeException('Status atau total tagihan tidak valid.');
            $pdo->prepare('UPDATE spmb_registrations SET student_name=?,student_nik=?,nisn=?,gender=?,birth_place=?,birth_date=?,parent_name=?,parent_nik=?,family_card_number=?,whatsapp=?,entry_class=?,previous_school=?,address=?,registration_status=?,document_status=?,total_due=?,payment_notes=? WHERE id=?')
                ->execute([$name,trim((string)($_POST['student_nik']??''))?:null,$nisn?:null,($_POST['gender']??'')?:null,trim((string)($_POST['birth_place']??''))?:null,($_POST['birth_date']??'')?:null,$parent,trim((string)($_POST['parent_nik']??''))?:null,trim((string)($_POST['family_card_number']??''))?:null,$wa,$class?:null,trim((string)($_POST['previous_school']??''))?:null,trim((string)($_POST['address']??''))?:null,$status,in_array($_POST['document_status']??'',['belum_lengkap','lengkap','terverifikasi'],true)?$_POST['document_status']:'belum_lengkap',$due,trim((string)($_POST['payment_notes']??''))?:null,$id]);
            spmb_update_student_number($pdo,$id);
            spmb_recalculate_payment($pdo,$id,(int)portal_user()['id']);
            portal_log($pdo,'update_registration','Memperbarui pendaftar SPMB #'.$id,school_unit_slug($existing['level']));
            portal_flash('success','Data pendaftar dan tagihan diperbarui.');
        } elseif ($action === 'add_payment') {
            $claimId=spmb_add_payment_claim($pdo,$id,$_POST,$_FILES['proof']??null,'staff');
            portal_log($pdo,'payment_claim','Mencatat klaim pembayaran #'.$claimId);
            portal_flash('success','Pembayaran masuk antrean pemeriksaan. Total belum bertambah.');
        } elseif ($action === 'review_claim') {
            $decision=(string)($_POST['decision']??'');
            $review=spmb_review_payment_claim($pdo,(int)($_POST['claim_id']??0),'portal',(int)portal_user()['id'],null,$decision,trim((string)($_POST['confirmed_amount']??'')),trim((string)($_POST['bank_reference']??'')),trim((string)($_POST['review_notes']??'')));
            portal_log($pdo,'review_payment','Bukti pembayaran #'.(int)$_POST['claim_id'].' '.$decision,school_unit_slug($review['claim']['level']));
            portal_flash('success',$decision==='verified'?'Pembayaran disetujui. Total terverifikasi sekarang '.spmb_portal_rupiah($review['total']).'.':'Bukti ditolak. Total terverifikasi tidak berubah.');
        } elseif ($action === 'void_claim') {
            $claimId=(int)($_POST['claim_id']??0);
            $total=spmb_void_payment_claim($pdo,$claimId,'portal',(int)portal_user()['id'],null,(string)($_POST['reason']??''));
            portal_log($pdo,'void_payment','Membatalkan verifikasi pembayaran #'.$claimId);
            portal_flash('success','Verifikasi dibatalkan. Total terbayar dihitung ulang menjadi '.spmb_portal_rupiah($total).'.');
        } elseif ($action === 'cancel_payment') {
            $paymentId=(int)($_POST['payment_id']??0);
            $pdo->prepare("UPDATE spmb_payments SET status='cancelled' WHERE id=? AND registration_id=? AND status='verified'")->execute([$paymentId,$id]);
            spmb_recalculate_payment($pdo,$id,(int)portal_user()['id']);
            portal_log($pdo,'cancel_payment','Membatalkan transaksi lama #'.$paymentId);
            portal_flash('success','Transaksi lama dibatalkan dan total dihitung ulang.');
        } else throw new RuntimeException('Tindakan tidak dikenal.');
    } catch (Throwable $error) { portal_flash('danger',$error->getMessage()); }
    header('Location: ' . SITE_URL . '/portal/payments');exit;
}

$all=$pdo->query('SELECT * FROM spmb_registrations ORDER BY created_at DESC,id DESC')->fetchAll();
$query=trim((string)($_GET['q']??''));$unitFilter=(string)($_GET['unit']??'');$yearFilter=(string)($_GET['year']??'');$statusFilter=(string)($_GET['status']??'');
$filtered=array_values(array_filter($all,static function(array $row) use($query,$unitFilter,$yearFilter,$statusFilter):bool {
    if ($unitFilter!=='' && school_unit_slug($row['level'])!==$unitFilter) return false;
    if ($yearFilter!=='' && $row['academic_year']!==$yearFilter) return false;
    if ($statusFilter!=='' && $row['payment_status']!==$statusFilter) return false;
    if ($query!=='') { $text=implode(' ',[(string)$row['registration_number'],(string)$row['student_name'],(string)$row['parent_name'],(string)$row['whatsapp'],(string)$row['nisn']]); if (mb_stripos($text,$query)===false) return false; }
    return true;
}));
if (($_GET['export']??'')==='csv') {
    header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="rekap-spmb-'.date('Ymd-His').'.csv"');
    $out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Kode SPMB','Sumber','Unit','Kelas','Nama Siswa','NISN','NIS Internal','Tahun Ajaran','Orang Tua','WhatsApp','Status','Total Tagihan','Terbayar Terverifikasi','Tanggal Daftar']);
    foreach($filtered as $row) fputcsv($out,array_map('spmb_csv_safe',[$row['registration_number'],$row['registration_source'],$row['level'],$row['entry_class'],$row['student_name'],$row['nisn'],$row['student_number'],$row['academic_year'],$row['parent_name'],$row['whatsapp'],$row['payment_status'],$row['total_due'],$row['payment_amount'],$row['created_at']]));fclose($out);exit;
}
$selectedId=(int)($_GET['edit']??$_GET['pay']??$_GET['created']??$_GET['link']??0);$selected=null;
if($selectedId){$stmt=$pdo->prepare('SELECT * FROM spmb_registrations WHERE id=?');$stmt->execute([$selectedId]);$selected=$stmt->fetch()?:null;}
$paymentLink=$selected?spmb_payment_url(spmb_payment_link_token($pdo,(int)$selected['id'])):null;
$pending=$pdo->query("SELECT c.*,r.student_name,r.registration_number,r.level FROM spmb_payment_claims c JOIN spmb_registrations r ON r.id=c.registration_id WHERE c.status='pending' ORDER BY c.created_at DESC,c.id DESC")->fetchAll();
$history=$pdo->query("SELECT c.*,r.student_name,r.registration_number,r.level FROM spmb_payment_claims c JOIN spmb_registrations r ON r.id=c.registration_id WHERE c.status<>'pending' ORDER BY c.reviewed_at DESC,c.id DESC LIMIT 60")->fetchAll();
$legacyTransactions=$pdo->query('SELECT p.*,r.student_name,r.registration_number FROM spmb_payments p JOIN spmb_registrations r ON r.id=p.registration_id ORDER BY p.created_at DESC,p.id DESC LIMIT 30')->fetchAll();
$today=date('Y-m-d');$todayRegistrations=0;$unitStats=[];foreach($unitLabels as $key=>$label)$unitStats[$key]=['registrations'=>0,'today'=>0,'paid'=>0.0,'pending'=>0];
foreach($all as $row){$key=school_unit_slug($row['level']);if(!isset($unitStats[$key]))continue;$unitStats[$key]['registrations']++;$unitStats[$key]['paid']+=(float)$row['payment_amount'];if(substr((string)$row['created_at'],0,10)===$today){$unitStats[$key]['today']++;$todayRegistrations++;}}
foreach($pending as $claim){$key=school_unit_slug($claim['level']);if(isset($unitStats[$key]))$unitStats[$key]['pending']++;}
$verifiedToday=(float)$pdo->query("SELECT COALESCE(SUM(claimed_amount),0) FROM spmb_payment_claims WHERE status='verified' AND DATE(reviewed_at)=CURDATE()")->fetchColumn();
$portalTitle='SPMB & Pembayaran';$portalActive='payments';require __DIR__.'/../../components/portal-header.php';
?>
<style>
.spmb-admin-head{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}.spmb-admin-head h2{margin:0}.spmb-admin-head p{margin:6px 0 0;color:var(--portal-muted)}.spmb-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:20px 0}.spmb-metric{background:#fff;border:1px solid #e3eae5;border-radius:15px;padding:20px;box-shadow:0 10px 26px #122f2110}.spmb-metric small{display:block;color:#65776d}.spmb-metric strong{display:block;font-size:1.55rem;color:#075a42;margin:7px 0}.spmb-unit-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.spmb-unit-card{padding:16px;border:1px solid #d9e8dd;border-radius:13px;background:#f4faf5}.spmb-unit-card strong{display:block;margin-bottom:8px}.spmb-unit-card small{display:block;color:#54685b;line-height:1.6}.spmb-section{margin-top:20px}.spmb-queue{display:grid;gap:14px}.spmb-claim{border:1px solid #dbe8df;border-radius:14px;padding:17px;background:#fbfdfa}.spmb-claim-top{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.spmb-claim-top strong{font-size:1.05rem}.spmb-claim form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:15px}.spmb-claim label{font-size:.75rem;font-weight:700}.spmb-claim input,.spmb-claim textarea{width:100%;margin-top:5px;padding:9px;border:1px solid #cbdace;border-radius:7px}.spmb-claim .wide{grid-column:1/-1}.spmb-claim .actions{grid-column:1/-1;display:flex;gap:8px}.spmb-claim button{border:0;background:#086648;color:#fff;border-radius:8px;padding:10px 14px;font-weight:800;cursor:pointer}.spmb-claim button.reject{background:#ad3a31}.spmb-tip{background:#eaf6ee;color:#27533d;padding:12px 14px;border-radius:9px;margin:12px 0}.spmb-table-wrap{overflow:auto}.spmb-table-wrap table{min-width:970px}.spmb-manual summary{font-weight:800;color:#075a42;cursor:pointer;padding:4px 0}.spmb-manual .portal-form{margin-top:18px}@media(max-width:1050px){.spmb-metrics,.spmb-unit-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.spmb-metrics,.spmb-unit-grid,.spmb-claim form{grid-template-columns:1fr}}
</style>
<div class="spmb-admin-head"><div><h2>Ruang Kerja SPMB</h2><p>Pendaftaran online dan input manual dari Daycare, TKIT, SDIT, serta SMPIT.</p></div><a class="portal-action" href="#manual-registration">+ Input Pendaftar Manual</a></div>
<div class="spmb-metrics"><div class="spmb-metric"><small>Pendaftar hari ini</small><strong><?php echo $todayRegistrations; ?></strong><span>Semua unit</span></div><div class="spmb-metric"><small>Bukti perlu diperiksa</small><strong><?php echo count($pending); ?></strong><span>Cocokkan dengan mutasi</span></div><div class="spmb-metric"><small>Terverifikasi hari ini</small><strong><?php echo spmb_portal_rupiah($verifiedToday); ?></strong><span>Setelah persetujuan petugas</span></div><div class="spmb-metric"><small>Total pendaftar</small><strong><?php echo count($all); ?></strong><span>Online dan manual</span></div></div>
<section class="portal-panel"><div class="panel-head"><h3>Ringkasan per Unit</h3></div><div class="spmb-unit-grid"><?php foreach($unitStats as $key=>$stat): ?><div class="spmb-unit-card"><strong><?php echo esc($unitLabels[$key]); ?></strong><small>Hari ini: <?php echo $stat['today']; ?> · Total: <?php echo $stat['registrations']; ?></small><small>Perlu dicek: <?php echo $stat['pending']; ?></small><small>Terverifikasi: <?php echo spmb_portal_rupiah($stat['paid']); ?></small></div><?php endforeach; ?></div></section>
<?php if($selected): ?><section class="portal-panel spmb-section"><div class="panel-head"><h3><?php echo esc($selected['student_name']); ?> · <?php echo esc($selected['registration_number']); ?></h3><a href="<?php echo SITE_URL; ?>/portal/payments">Tutup</a></div><p><strong><?php echo esc($selected['level']); ?></strong> · <?php echo esc($selected['entry_class'] ?: 'Kelas belum ditentukan'); ?> · <?php echo esc($selected['academic_year']); ?></p><p class="spmb-tip">Tautan aman untuk orang tua mengirim bukti: <a href="<?php echo esc($paymentLink); ?>" target="_blank" rel="noopener"><?php echo esc($paymentLink); ?></a></p>
<?php if(isset($_GET['edit'])||isset($_GET['created'])||isset($_GET['link'])): ?><form method="post" class="portal-form portal-form-grid"><input type="hidden" name="_token" value="<?php echo esc(portal_csrf_token()); ?>"><input type="hidden" name="action" value="update_registration"><input type="hidden" name="id" value="<?php echo (int)$selected['id']; ?>">
<div class="field"><label>Nama calon siswa<input name="student_name" value="<?php echo esc($selected['student_name']); ?>" required></label></div><div class="field"><label>NIK siswa<input name="student_nik" value="<?php echo esc($selected['student_nik']); ?>"></label></div><div class="field"><label>NISN lama (opsional)<input name="nisn" inputmode="numeric" pattern="[0-9]{10}" maxlength="10" value="<?php echo esc($selected['nisn']); ?>"></label></div><div class="field"><label>NIS internal<input value="<?php echo esc($selected['student_number'] ?: 'Dibuat setelah daftar ulang'); ?>" disabled></label></div>
<div class="field"><label>Jenis kelamin<select name="gender"><option value="">-- Pilih --</option><option value="L" <?php echo $selected['gender']==='L'?'selected':''; ?>>Laki-laki</option><option value="P" <?php echo $selected['gender']==='P'?'selected':''; ?>>Perempuan</option></select></label></div><div class="field"><label>Tempat lahir<input name="birth_place" value="<?php echo esc($selected['birth_place']); ?>"></label></div><div class="field"><label>Tanggal lahir<input type="date" name="birth_date" value="<?php echo esc($selected['birth_date']); ?>"></label></div><div class="field"><label>Kelas tujuan<select name="entry_class"><option value="">Belum ditentukan</option><?php foreach(spmb_entry_classes($selected['level']) as $class): ?><option value="<?php echo esc($class); ?>" <?php echo $selected['entry_class']===$class?'selected':''; ?>><?php echo esc($class); ?></option><?php endforeach; ?></select></label></div>
<div class="field"><label>Nama orang tua<input name="parent_name" value="<?php echo esc($selected['parent_name']); ?>" required></label></div><div class="field"><label>NIK orang tua<input name="parent_nik" value="<?php echo esc($selected['parent_nik']); ?>"></label></div><div class="field"><label>No. KK<input name="family_card_number" value="<?php echo esc($selected['family_card_number']); ?>"></label></div><div class="field"><label>WhatsApp<input name="whatsapp" value="<?php echo esc($selected['whatsapp']); ?>" required></label></div>
<div class="field"><label>Asal sekolah<input name="previous_school" value="<?php echo esc($selected['previous_school']); ?>"></label></div><div class="field"><label>Status pendaftaran<select name="registration_status"><?php foreach($statuses as $key=>$label): ?><option value="<?php echo $key; ?>" <?php echo $selected['registration_status']===$key?'selected':''; ?>><?php echo esc($label); ?></option><?php endforeach; ?></select></label></div><div class="field"><label>Status dokumen<select name="document_status"><?php foreach(['belum_lengkap'=>'Belum Lengkap','lengkap'=>'Lengkap','terverifikasi'=>'Terverifikasi'] as $key=>$label): ?><option value="<?php echo $key; ?>" <?php echo $selected['document_status']===$key?'selected':''; ?>><?php echo esc($label); ?></option><?php endforeach; ?></select></label></div><div class="field"><label>Total tagihan (Rp)<input type="number" min="0" step="1" name="total_due" value="<?php echo (int)$selected['total_due']; ?>" required></label></div><div class="field full"><label>Alamat<textarea name="address"><?php echo esc($selected['address']); ?></textarea></label></div><div class="field full"><label>Catatan internal<textarea name="payment_notes"><?php echo esc($selected['payment_notes']); ?></textarea></label></div><div class="field full"><button class="portal-action">Simpan Data dan Tagihan</button></div></form><?php endif; ?>
<?php if(isset($_GET['pay'])): ?><form method="post" enctype="multipart/form-data" class="portal-form portal-form-grid"><input type="hidden" name="_token" value="<?php echo esc(portal_csrf_token()); ?>"><input type="hidden" name="action" value="add_payment"><input type="hidden" name="id" value="<?php echo (int)$selected['id']; ?>"><div class="field"><label>Jenis pembayaran<select name="payment_type"><?php foreach(['Pembayaran SPMB','Formulir Pendaftaran','Daftar Ulang','Uang Pangkal','Seragam','SPP','Lainnya'] as $type): ?><option><?php echo esc($type); ?></option><?php endforeach; ?></select></label></div><div class="field"><label>Nominal (Rp)<input type="number" min="1" step="1" name="amount" required></label></div><div class="field"><label>Metode<select name="payment_method"><?php foreach(['Transfer Bank','Tunai','QRIS','Virtual Account'] as $method): ?><option><?php echo esc($method); ?></option><?php endforeach; ?></select></label></div><div class="field"><label>Tanggal<input type="date" name="payment_date" value="<?php echo date('Y-m-d'); ?>" required></label></div><div class="field"><label>Nama penyetor<input name="payer_name" value="<?php echo esc($selected['parent_name']); ?>"></label></div><div class="field"><label>Referensi bank (jika ada)<input name="reference_number"></label></div><div class="field full"><label>Bukti gambar (opsional untuk input petugas)<input type="file" name="proof" accept="image/jpeg,image/png,image/webp"></label></div><div class="field full"><p class="spmb-tip">Transaksi dicatat sebagai <strong>menunggu pemeriksaan</strong>. Total terbayar bertambah setelah disetujui.</p><button class="portal-action">Catat Pembayaran</button></div></form><?php endif; ?></section><?php endif; ?>
<section class="portal-panel spmb-section spmb-manual" id="manual-registration"><details <?php echo isset($_GET['new'])?'open':''; ?>><summary>+ Input Pendaftar Manual (Kasir / Admin)</summary><p>Gunakan formulir ini untuk pendaftar yang datang langsung ke sekolah. Kode SPMB dan tautan pembayaran dibuat otomatis.</p><form method="post" class="portal-form portal-form-grid"><input type="hidden" name="_token" value="<?php echo esc(portal_csrf_token()); ?>"><input type="hidden" name="action" value="manual_registration"><div class="field"><label>Nama calon siswa *<input name="student_name" required></label></div><div class="field"><label>Nama orang tua *<input name="parent_name" required></label></div><div class="field"><label>WhatsApp *<input name="whatsapp" required></label></div><div class="field"><label>Unit *<select name="level" id="manualLevel" required><option value="">Pilih unit</option><?php foreach($spmbLevels as $level=>$label): ?><option value="<?php echo esc($level); ?>"><?php echo esc($label); ?></option><?php endforeach; ?></select></label></div><div class="field"><label>Kelas tujuan *<select name="entry_class" id="manualClass" required><option value="">Pilih unit dahulu</option></select></label></div><div class="field"><label>Tahun ajaran *<select name="academic_year"><?php foreach($academicYears as $year=>$track): ?><option value="<?php echo esc($year); ?>"><?php echo esc($year); ?> · <?php echo esc($track); ?></option><?php endforeach; ?></select></label></div><div class="field"><label>NISN lama (opsional)<input name="nisn" inputmode="numeric" pattern="[0-9]{10}" maxlength="10"></label></div><div class="field"><label>NIK siswa<input name="student_nik"></label></div><div class="field"><label>Jenis kelamin<select name="gender"><option value="">-- Pilih --</option><option value="L">Laki-laki</option><option value="P">Perempuan</option></select></label></div><div class="field"><label>Tempat lahir<input name="birth_place"></label></div><div class="field"><label>Tanggal lahir<input type="date" name="birth_date"></label></div><div class="field"><label>NIK orang tua<input name="parent_nik"></label></div><div class="field"><label>No. KK<input name="family_card_number"></label></div><div class="field"><label>Asal sekolah<input name="previous_school"></label></div><div class="field full"><label>Alamat<textarea name="address"></textarea></label></div><div class="field full"><button class="portal-action">Buat Pendaftar</button></div></form></details></section>
<section class="portal-panel spmb-section"><div class="panel-head"><h3>Antrean Bukti Pembayaran (<?php echo count($pending); ?>)</h3></div><p class="spmb-tip">Cocokkan tanggal, nama, nominal, dan nomor referensi dengan mutasi rekening sebelum memilih Setujui. Screenshot saja belum membuktikan dana masuk.</p><div class="spmb-queue"><?php foreach($pending as $claim): ?><div class="spmb-claim"><div class="spmb-claim-top"><div><strong><?php echo esc($claim['student_name']); ?> · <?php echo spmb_portal_rupiah($claim['claimed_amount']); ?></strong><br><small><?php echo esc($claim['registration_number']); ?> · <?php echo esc($claim['level']); ?> · <?php echo esc($claim['payment_date']); ?> · <?php echo esc($claim['payment_method']); ?></small></div><div><?php if($claim['proof_path']): ?><a class="portal-action secondary small" target="_blank" rel="noopener" href="?proof=<?php echo (int)$claim['id']; ?>">Lihat Bukti</a><?php endif; ?></div></div><form method="post"><input type="hidden" name="_token" value="<?php echo esc(portal_csrf_token()); ?>"><input type="hidden" name="action" value="review_claim"><input type="hidden" name="claim_id" value="<?php echo (int)$claim['id']; ?>"><label>Nominal di mutasi (Rp)<input name="confirmed_amount" type="number" min="1" step="1" value="<?php echo (int)$claim['claimed_amount']; ?>"></label><label>Referensi mutasi / transaksi<input name="bank_reference" value="<?php echo esc($claim['reference_number']); ?>" placeholder="Wajib untuk transfer"></label><label>Catatan pemeriksaan<input name="review_notes" placeholder="Alasan wajib jika ditolak"></label><div class="actions"><button name="decision" value="verified">Setujui &amp; Akumulasikan</button><button class="reject" name="decision" value="rejected">Tolak</button></div></form></div><?php endforeach; ?><?php if(!$pending): ?><p class="empty-state">Tidak ada bukti yang menunggu pemeriksaan.</p><?php endif; ?></div></section>
<section class="portal-panel spmb-section"><div class="panel-head"><h3>Riwayat Pemeriksaan</h3></div><div class="spmb-table-wrap"><table class="portal-table"><thead><tr><th>Pendaftar</th><th>Nominal</th><th>Referensi</th><th>Status</th><th>Diperiksa</th><th>Aksi</th></tr></thead><tbody><?php foreach($history as $claim): ?><tr><td><?php echo esc($claim['student_name']); ?><br><small><?php echo esc($claim['registration_number']); ?></small></td><td><?php echo spmb_portal_rupiah($claim['claimed_amount']); ?></td><td><?php echo esc($claim['verified_reference'] ?: $claim['reference_number'] ?: '-'); ?></td><td><?php echo esc(['verified'=>'Terverifikasi','rejected'=>'Ditolak','voided'=>'Dibatalkan'][$claim['status']] ?? $claim['status']); ?><?php if($claim['review_notes']): ?><br><small><?php echo esc($claim['review_notes']); ?></small><?php endif; ?></td><td><?php echo esc($claim['reviewed_at'] ?: '-'); ?></td><td><?php if($claim['proof_path']): ?><a class="portal-action secondary small" href="?proof=<?php echo (int)$claim['id']; ?>" target="_blank" rel="noopener">Bukti</a><?php endif; ?><?php if($claim['status']==='verified'): ?><form method="post" style="margin-top:6px"><input type="hidden" name="_token" value="<?php echo esc(portal_csrf_token()); ?>"><input type="hidden" name="action" value="void_claim"><input type="hidden" name="claim_id" value="<?php echo (int)$claim['id']; ?>"><input name="reason" placeholder="Alasan pembatalan" required><button class="portal-action danger small">Batalkan verifikasi</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$history): ?><tr><td colspan="6">Belum ada pembayaran yang diperiksa.</td></tr><?php endif; ?></tbody></table></div></section>
<?php if($legacyTransactions): ?><section class="portal-panel spmb-section"><div class="panel-head"><h3>Transaksi Sebelum Alur Bukti</h3></div><div class="spmb-table-wrap"><table class="portal-table"><thead><tr><th>Kuitansi</th><th>Siswa</th><th>Nominal</th><th>Tanggal</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($legacyTransactions as $payment): ?><tr><td><?php echo esc($payment['receipt_number']); ?></td><td><?php echo esc($payment['student_name']); ?></td><td><?php echo spmb_portal_rupiah($payment['amount']); ?></td><td><?php echo esc($payment['payment_date']); ?></td><td><?php echo $payment['status']==='verified'?'Terverifikasi':'Dibatalkan'; ?></td><td><?php if($payment['status']==='verified'): ?><form method="post" onsubmit="return confirm('Batalkan transaksi lama ini?')"><input type="hidden" name="_token" value="<?php echo esc(portal_csrf_token()); ?>"><input type="hidden" name="action" value="cancel_payment"><input type="hidden" name="id" value="<?php echo (int)$payment['registration_id']; ?>"><input type="hidden" name="payment_id" value="<?php echo (int)$payment['id']; ?>"><button class="portal-action danger small">Batalkan</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<section class="portal-panel spmb-section"><div class="panel-head"><h3>Semua Pendaftar (<?php echo count($filtered); ?>)</h3><a class="portal-action secondary small" href="?<?php echo esc(http_build_query(['q'=>$query,'unit'=>$unitFilter,'year'=>$yearFilter,'status'=>$statusFilter,'export'=>'csv'])); ?>">Ekspor CSV</a></div><form class="filters" method="get"><input name="q" value="<?php echo esc($query); ?>" placeholder="Kode, siswa, orang tua, WA, NISN"><select name="unit"><option value="">Semua unit</option><?php foreach($unitLabels as $key=>$label): ?><option value="<?php echo $key; ?>" <?php echo $unitFilter===$key?'selected':''; ?>><?php echo esc($label); ?></option><?php endforeach; ?></select><select name="year"><option value="">Semua tahun</option><?php foreach($academicYears as $year=>$track): ?><option value="<?php echo esc($year); ?>" <?php echo $yearFilter===$year?'selected':''; ?>><?php echo esc($year); ?></option><?php endforeach; ?></select><select name="status"><option value="">Semua status</option><?php foreach(['belum_bayar'=>'Belum bayar','sebagian'=>'Sebagian','lunas'=>'Lunas'] as $key=>$label): ?><option value="<?php echo $key; ?>" <?php echo $statusFilter===$key?'selected':''; ?>><?php echo $label; ?></option><?php endforeach; ?></select><button class="portal-action small">Filter</button></form><div class="spmb-table-wrap"><table class="portal-table"><thead><tr><th>Kode / Siswa</th><th>Unit / Kelas</th><th>Orang Tua</th><th>Asal</th><th>Tagihan</th><th>Terverifikasi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($filtered as $row): ?><tr><td><strong><?php echo esc($row['student_name']); ?></strong><br><small><?php echo esc($row['registration_number']); ?></small></td><td><?php echo esc($row['level']); ?><br><small><?php echo esc($row['entry_class'] ?: '-'); ?></small></td><td><?php echo esc($row['parent_name']); ?><br><small><?php echo esc($row['whatsapp']); ?></small></td><td><?php echo $row['registration_source']==='manual'?'Manual':'Online'; ?></td><td><?php echo spmb_portal_rupiah($row['total_due']); ?></td><td><?php echo spmb_portal_rupiah($row['payment_amount']); ?></td><td><?php echo esc(ucwords(str_replace('_',' ',$row['payment_status']))); ?></td><td><div class="table-actions"><a class="portal-action secondary small" href="?edit=<?php echo (int)$row['id']; ?>">Detail</a><a class="portal-action small" href="?pay=<?php echo (int)$row['id']; ?>">Catat Bayar</a></div></td></tr><?php endforeach; ?><?php if(!$filtered): ?><tr><td colspan="8">Belum ada pendaftar sesuai filter.</td></tr><?php endif; ?></tbody></table></div></section>
<script>
(() => { const level=document.getElementById('manualLevel'),target=document.getElementById('manualClass'); if(!level||!target)return; const classes=<?php echo json_encode(array_map('spmb_entry_classes',array_keys($spmbLevels)),JSON_UNESCAPED_UNICODE|JSON_HEX_TAG); ?>,levels=<?php echo json_encode(array_keys($spmbLevels),JSON_UNESCAPED_UNICODE|JSON_HEX_TAG); ?>; level.addEventListener('change',()=>{target.replaceChildren(new Option('Pilih kelas','')); const index=levels.indexOf(level.value);for(const name of index<0?[]:classes[index])target.add(new Option(name,name));});})();
</script>
